/**
 * @function paginate
 * @description Implements pagination logic. 
 * @param {Array<T>} data The array to paginate.
 * @param {number} page The one-based page number.
 * @param {number} size The number of items per page.
 * @returns {Array<T>} The paginated data array.
 */
function paginate(data, page, size) {
    // Nonpositive or noninteger page or size returns an empty array.
    if (page <= 0 || !Number.isInteger(page) || size <= 0 || !Number.isInteger(size)) {
        return [];
    }

    const totalItems = data.length;
    const startIndex = (page - 1) * size;
    const endIndex = startIndex + size;

    // Out-of-range page returns an empty array.
    if (startIndex >= totalItems) {
        return [];
    }

    // Return the slice of the data
    return data.slice(startIndex, endIndex);
}

module.exports = {
    paginate: paginate
};
